        "TeacherSub", "SpecialSub", "DepartmentSub", "InsuSalary", "TotalSalary",
        "InsuMoney", "DeductedSalary", "DeltaMoney", "NetSalary", "Description"
    };
    options.TotalColumns = new string[] { "N", "O", "P", "Q", "R", "S" };
    options.TotalFields = new string[] { "InsuSalary", "TotalSalary", "InsuMoney", "DeductedSalary", "DeltaMoney", "NetSalary" };
    options.RequiredFields = new string[] { "DepartmentName", "Fullname", "InsuSalary", "TotalSalary", "InsuMoney", "DeductedSalary", "DeltaMoney", "NetSalary" };
    options.FieldRules = new ExcelFieldRule[] {
        CreateRule("OverFrameSub", 100m, false),
        CreateRule("TeacherSub", 100m, false),
        CreateRule("SpecialSub", 100m, false),
        CreateRule("DepartmentSub", 100m, false),
        CreateRule("BankAccount", 0m, true)
    };
    options.CellWrites = new ExcelCellWrite[] {
        CreateCell(4, "C", "BẢNG LƯƠNG THÁNG " + month.ToString("M/yyyy", CultureInfo.InvariantCulture))
    };
}
```

Khóa nhóm dùng chung cho cả ba mẫu, khai trong `CreateOptions`: cắt theo `DepartmentID`, không có thì `DepartmentName`, số nhóm La Mã ở cột A, hàng nhóm 10, hàng chi tiết 11, chân từ hàng 12.

Mẫu khác sau này gọi thẳng thư viện, cùng kiểu với đoạn trên:

```csharp
ExcelGroupOptions options = new ExcelGroupOptions();
options.GroupPrototypeRow = 10;
options.DetailPrototypeRow = 11;
options.FooterStartRow = 12;
options.GroupKeyField = "DepartmentID";
options.GroupKeyFallbackField = "DepartmentName";
options.GroupTitleField = "DepartmentName";
options.GroupTitleColumn = "C";
options.GroupOrderColumn = "A";
options.GroupOrderAsRoman = true;
options.DetailFields = new string[] { "@GlobalOrder", "@DepartmentOrder", "Fullname" };
options.TotalColumns = new string[] { "N", "O", "P", "Q", "R", "S" };
options.TotalFields = new string[] { "InsuSalary", "TotalSalary", "InsuMoney", "DeductedSalary", "DeltaMoney", "NetSalary" };
ExcelGroupExporter.Export(dtbExport, duongDanMau, duongDanLuu, options);
```

`@GlobalOrder` là số cả bảng, `@DepartmentOrder` là số trong nhóm. `TotalColumns` và `TotalFields` đi cặp nhau để ghi `SUM` trên dòng phòng ban. `FieldRules` với `DivideBy = 100` dùng cho phụ cấp đang lưu dạng phần trăm. `ForceText = true` giữ số 0 đầu của số tài khoản.

File mẫu phải có hàng nhóm và hàng chi tiết đúng số hàng khai trong options. Dữ liệu cần các cột trong `RequiredFields`, và các dòng cùng phòng ban sẽ được xếp lại theo `Department_OrderIndex` rồi tên phòng ban.

`Libs.CExcel.ExportTemplateExcel` trong sổ đầu bài vẫn là lối xuất danh sách phẳng. Muốn sổ đó ra dòng nhóm thì làm một `ExcelGroupOptions` riêng (khóa nhóm, cột chi tiết, hàng mẫu trong file `Bang ghi tom tat noi dung.xlsx`) rồi gọi `ExcelGroupExporter`, không nhét thêm tham số vào `CExcel`.

