using System;
using System.Collections;
using System.Collections.Generic;
using System.Data;
using System.Globalization;
using System.IO;
using System.Reflection;
using System.Xml;
namespace TKSManager.Salary
{
    /// <summary>
    /// Bộ tham số cho <see cref="ExcelGroupExporter"/>.
    /// File mẫu .xlsx phải có đúng một hàng nhóm và một hàng chi tiết.
    /// Mọi hàng từ hàng nhóm trở xuống bị xóa rồi ghi lại. Phần chân (chữ ký) được đẩy xuống dưới dữ liệu.
    /// Hàng nằm giữa hàng chi tiết và phần chân (hàng ví dụ) bị bỏ, không ra file.
    /// Thư viện tìm hàng theo số dòng, không tìm chữ trong ô. Gõ "GroupIDTest" hay "DateText" vào ô mẫu không tạo liên kết cột.
    /// Chỉ sửa sheet1. Tiêu đề dạng {Lớp} không tự thay; muốn đổi ô phía trên hàng nhóm thì dùng <see cref="CellWrites"/>.
    /// </summary>
    /// <example>
    /// Sổ đầu bài, nhóm theo GroupIDTest, tên nhóm là GroupIDTestName.
    /// File mẫu: hàng 8 là dòng nhóm (gộp A:G), hàng 9 là dòng DateText, hàng 12 là "Đồng Nai, ngày...".
    /// <code>
    /// ExcelGroupOptions options = new ExcelGroupOptions();
    /// options.GroupPrototypeRow = 8;
    /// options.DetailPrototypeRow = 9;
    /// options.FooterStartRow = 12;
    /// options.GroupKeyField = "GroupIDTest";
    /// options.GroupKeyFallbackField = "GroupIDTestName";
    /// options.GroupTitleField = "GroupIDTestName";
    /// options.GroupTitleColumn = "A";
    /// options.GroupOrderAsRoman = false;
    /// options.DetailFields = new string[] {
    ///     "DateText", "TheoryQuantity", "PracticeQuantity", "TestQuantity",
    ///     "LearningContent", "RequestContent", "OffStudentCountText", "Rating", "Description"
    /// };
    /// options.RequiredFields = new string[] { "GroupIDTestName", "DateText" };
    /// ExcelSortField sortGroup = new ExcelSortField();
    /// sortGroup.UseGroupKey = true;
    /// options.SortFields = new ExcelSortField[] { sortGroup };
    /// ExcelGroupExporter.Export(dtbExport, duongDanMau, duongDanLuu, options);
    /// </code>
    /// Bảng lương mẫu 1, 2, 3 xem SalaryExcelExporter.CreateOptions.
    /// </example>
    public class ExcelGroupOptions
    {
        /// <summary>
        /// Số hàng mẫu của dòng nhóm trong file .xlsx, đếm từ 1.
        /// Hàng này được clone cho mỗi nhóm. Style, border và vùng gộp ngang trên đúng hàng này được copy sang từng dòng nhóm mới.
        /// Phải nhỏ hơn <see cref="DetailPrototypeRow"/>.
        /// Ví dụ sổ đầu bài: 8 (hàng vừa chèn ngay trên hàng DateText).
        /// Ví dụ lương: 10.
        /// </summary>
        public int GroupPrototypeRow;
        /// <summary>
        /// Số hàng mẫu của dòng chi tiết, đếm từ 1.
        /// Mỗi DataRow clone hàng này một lần. Nội dung ô mẫu bị xóa, style giữ lại.
        /// Ví dụ sổ đầu bài: 9 sau khi đã chèn hàng nhóm (hàng đang thấy chữ DateText).
        /// Ví dụ lương: 11.
        /// </summary>
        public int DetailPrototypeRow;
        /// <summary>
        /// Hàng đầu tiên của phần chân (chữ ký, ngày tháng). Các hàng từ số này trở xuống được giữ và đẩy xuống dưới danh sách.
        /// Truyền 0 thì thư viện lấy <see cref="DetailPrototypeRow"/> + 1.
        /// Ví dụ sổ đầu bài: 12, là hàng "Đồng Nai, ngày...". Hàng ví dụ 12/01/2019 nằm trước hàng này nên không ra file.
        /// Ví dụ lương: 12.
        /// </summary>
        public int FooterStartRow;
        /// <summary>
        /// Tên cột DataTable dùng để cắt nhóm. Cùng giá trị và đứng liền nhau sau khi sort thì vào một nhóm.
        /// Có giá trị thì khóa là "ID:" + giá trị cột này. DBNull thì dùng <see cref="GroupKeyFallbackField"/>.
        /// Ví dụ sổ đầu bài: "GroupIDTest". Ví dụ lương: "DepartmentID".
        /// </summary>
        public string GroupKeyField;
        /// <summary>
        /// Cột dùng làm khóa khi <see cref="GroupKeyField"/> thiếu hoặc ô đó là DBNull. Khóa dạng "NAME:" + chữ.
        /// Ví dụ sổ đầu bài: "GroupIDTestName". Ví dụ lương: "DepartmentName".
        /// Để trống thì fallback sang <see cref="GroupTitleField"/>.
        /// </summary>
        public string GroupKeyFallbackField;
        /// <summary>
        /// Tên cột DataTable ghi lên dòng nhóm. Lấy từ dòng đầu tiên của nhóm.
        /// Đây là chữ người dùng nhìn thấy, khác với khóa cắt nhóm.
        /// Ví dụ sổ đầu bài: "GroupIDTestName". Ví dụ lương: "DepartmentName".
        /// </summary>
        public string GroupTitleField;
        /// <summary>
        /// Cột Excel trên dòng nhóm để ghi <see cref="GroupTitleField"/>. Ví dụ "A", "B", "C".
        /// Để trống thì không ghi tên nhóm.
        /// Muốn tên trải nhiều cột thì gộp ô trên hàng mẫu nhóm trong file Excel. Thư viện copy vùng gộp đó.
        /// Sổ đầu bài thường để "A". Lương mẫu 1 để "C", mẫu 2 và 3 để "B".
        /// Trùng <see cref="GroupOrderColumn"/> thì tên ghi sau số, nên tên đè lên số.
        /// </summary>
        public string GroupTitleColumn;
        /// <summary>
        /// Cột Excel ghi số thứ tự nhóm (1, 2, 3 hoặc I, II, III). Để trống hoặc null thì dòng nhóm không có số.
        /// Ví dụ lương: "A". Sổ đầu bài không cần số thì để trống.
        /// Kiểu số hay La Mã do <see cref="GroupOrderAsRoman"/> quyết định.
        /// </summary>
        public string GroupOrderColumn;
        /// <summary>
        /// true: số nhóm ra La Mã (1 = I, 4 = IV, 9 = IX, 40 = XL). false: ra số thường 1, 2, 3.
        /// Chỉ có tác dụng khi <see cref="GroupOrderColumn"/> có giá trị. Lương đang truyền true. Sổ đầu bài truyền false.
        /// </summary>
        public bool GroupOrderAsRoman;
        /// <summary>
        /// Tên token trong <see cref="DetailFields"/> để ghi số thứ tự trên cả bảng, bắt đầu từ 1, không đọc DataTable.
        /// Ví dụ lương: "@GlobalOrder". Phần tử DetailFields trùng đúng chuỗi này thì ô đó là số cả bảng.
        /// Để trống thì không có cột đếm cả bảng. Tên token do chỗ gọi đặt, thư viện không gắn sẵn "@GlobalOrder".
        /// </summary>
        public string GlobalOrderField;
        /// <summary>
        /// Tên token trong <see cref="DetailFields"/> để ghi số thứ tự trong từng nhóm, bắt đầu lại từ 1 mỗi nhóm.
        /// Ví dụ lương: "@DepartmentOrder". Mẫu khác có thể truyền "@STT" miễn DetailFields dùng cùng chuỗi.
        /// Để trống thì không có cột đếm trong nhóm.
        /// </summary>
        public string GroupOrderField;
        /// <summary>
        /// Danh sách cột chi tiết. Phần tử 0 ghi vào cột A, phần tử 1 vào cột B, rồi C, D...
        /// Giá trị là tên cột DataTable, hoặc trùng <see cref="GlobalOrderField"/> / <see cref="GroupOrderField"/>.
        /// Cột không có trong DataTable thì ô để trống, không ném lỗi.
        /// Ví dụ sổ đầu bài, A đến I:
        /// "DateText", "TheoryQuantity", "PracticeQuantity", "TestQuantity", "LearningContent", "RequestContent", "OffStudentCountText", "Rating", "Description".
        /// Ví dụ lương mẫu 2: "@GlobalOrder", "Fullname", "PositionName", "UnitSalary", ... "Description".
        /// Bắt buộc có ít nhất một phần tử.
        /// </summary>
        public string[] DetailFields;
        /// <summary>
        /// Cột Excel trên dòng nhóm sẽ nhận công thức SUM. Đi cặp với <see cref="TotalFields"/>, cùng số phần tử, cùng thứ tự.
        /// Ví dụ lương mẫu 2: { "D", "E", "F", "G", "H" } là năm cột tiền, không gồm cột tên và cột diễn giải.
        /// Null khi dòng nhóm không cần cộng. Truyền một mảng mà thiếu mảng kia thì Export ném lỗi.
        /// </summary>
        public string[] TotalColumns;
        /// <summary>
        /// Tên cột DataTable dùng để cộng giá trị trên dòng nhóm. Cùng vị trí với <see cref="TotalColumns"/>.
        /// Ví dụ mẫu 2: { "UnitSalary", "DepartmentSubMoney", "InsuMoney", "DeltaMoney", "NetSalary" }
        /// thì ô D dòng nhóm = SUM cột D của các dòng chi tiết trong nhóm, đồng thời ghi sẵn tổng đã tính.
        /// DBNull bỏ qua, coi như 0. Cột thiếu trong DataTable thì Export ném lỗi.
        /// </summary>
        public string[] TotalFields;
        /// <summary>
        /// Thứ tự sắp DataRow trước khi cắt nhóm. Cắt nhóm chỉ gom các dòng đứng liền nhau cùng khóa.
        /// Null hoặc mảng rỗng thì giữ nguyên thứ tự DataTable.
        /// Nên có một phần tử UseGroupKey = true để các dòng cùng GroupIDTest đứng thành một khối.
        /// Ví dụ lương: Department_OrderIndex (Numeric), DepartmentName, UseGroupKey, Position_OrderIndex, LastName, FirstName, Fullname.
        /// </summary>
        public ExcelSortField[] SortFields;
        /// <summary>
        /// Ghi đè các ô nằm phía trên hàng nhóm (tiêu đề, header). Những hàng này không bị xóa khi đổ dữ liệu.
        /// Mỗi phần tử là một ô: số hàng, cột, chữ cần ghi.
        /// Ví dụ lương mẫu 1: hàng 4 cột C = "BẢNG LƯƠNG THÁNG 9/2026".
        /// Ví dụ sổ đầu bài, nếu ô B2 đang là "{Lớp}" và muốn ghi tên lớp: Row = 2, Column = "B", Text = tên lớp.
        /// Không quét cả sheet để thay mọi chữ {Lớp}. Ô nào cần đổi thì khai một phần tử.
        /// </summary>
        public ExcelCellWrite[] CellWrites;
        /// <summary>
        /// Quy tắc riêng cho một số cột chi tiết. Không khai thì cột số ghi số, cột chữ ghi chữ.
        /// DivideBy = 100 dùng khi DB lưu 100 nghĩa là 100% và Excel cần 1.
        /// ForceText = true dùng cho số tài khoản để giữ số 0 ở đầu.
        /// Ví dụ lương mẫu 1: OverFrameSub, TeacherSub, SpecialSub, DepartmentSub chia 100; BankAccount ép chữ.
        /// </summary>
        public ExcelFieldRule[] FieldRules;
        /// <summary>
        /// Cột DataTable bắt buộc phải có trước khi xuất. Thiếu thì ném ArgumentException, không tạo file dở.
        /// Null thì không kiểm tra thêm. <see cref="TotalFields"/> luôn được kiểm tra dù mảng này có khai hay không.
        /// Ví dụ sổ đầu bài: { "GroupIDTestName", "DateText" }.
        /// Ví dụ lương mẫu 1: DepartmentName, Fullname, InsuSalary, TotalSalary, InsuMoney, DeductedSalary, DeltaMoney, NetSalary.
        /// </summary>
        public string[] RequiredFields;
    }
    /// <summary>
    /// Một mức sắp xếp, truyền trong <see cref="ExcelGroupOptions.SortFields"/>.
    /// Nhiều phần tử thì so từ trái sang phải, mức trước khác nhau thì dừng.
    /// </summary>
    /// <example>
    /// Gom nhóm trước, trong nhóm xếp theo ngày dạng số:
    /// <code>
    /// ExcelSortField byGroup = new ExcelSortField();
    /// byGroup.UseGroupKey = true;
    /// ExcelSortField byDate = new ExcelSortField();
    /// byDate.Field = "SortDate";
    /// byDate.Numeric = false;
    /// options.SortFields = new ExcelSortField[] { byGroup, byDate };
    /// </code>
    /// </example>
    public class ExcelSortField
    {
        /// <summary>
        /// Tên cột DataTable để so sánh. Bỏ qua khi <see cref="UseGroupKey"/> = true.
        /// Ví dụ: "DepartmentName", "LastName", "DateText".
        /// </summary>
        public string Field;
        /// <summary>
        /// true: so như số nguyên. Ô trống hoặc DBNull xếp cuối (Int32.MaxValue).
        /// false: so như chữ, không phân biệt hoa thường theo CurrentCulture.
        /// Ví dụ Department_OrderIndex để true. DepartmentName để false.
        /// </summary>
        public bool Numeric;
        /// <summary>
        /// true: so theo khóa nhóm (GroupKeyField, rồi fallback), không dùng <see cref="Field"/>.
        /// Dùng khi cần các dòng cùng GroupIDTest đứng liền nhau trước khi cắt nhóm.
        /// </summary>
        public bool UseGroupKey;
    }
    /// <summary>
    /// Một ô tiêu đề cần ghi đè. Chỉ dùng cho hàng nằm trên <see cref="ExcelGroupOptions.GroupPrototypeRow"/>.
    /// </summary>
    /// <example>
    /// <code>
    /// ExcelCellWrite cell = new ExcelCellWrite();
    /// cell.Row = 4;
    /// cell.Column = "C";
    /// cell.Text = "BẢNG LƯƠNG THÁNG 9/2026";
    /// options.CellWrites = new ExcelCellWrite[] { cell };
    /// </code>
    /// </example>
    public class ExcelCellWrite
    {
        /// <summary>Số hàng Excel, đếm từ 1. Ví dụ hàng tiêu đề lương là 4. Hàng phải còn tồn tại sau khi xóa vùng dữ liệu.</summary>
        public int Row;
        /// <summary>Cột Excel, dạng chữ. Ví dụ "A", "C", "AA".</summary>
        public string Column;
        /// <summary>Chữ ghi vào ô. Null được ghi thành chuỗi rỗng. Xuống dòng trong ô thì đưa ký tự \n trong chuỗi.</summary>
        public string Text;
    }
    /// <summary>
    /// Quy tắc ghi một cột chi tiết. Field phải trùng tên trong <see cref="ExcelGroupOptions.DetailFields"/>.
    /// </summary>
    /// <example>
    /// Phụ cấp lưu 100 nghĩa là 100%, Excel hiển thị 1:
    /// <code>
    /// ExcelFieldRule rule = new ExcelFieldRule();
    /// rule.Field = "OverFrameSub";
    /// rule.DivideBy = 100m;
    /// rule.ForceText = false;
    /// </code>
    /// Số tài khoản giữ số 0 đầu:
    /// <code>
    /// ExcelFieldRule bank = new ExcelFieldRule();
    /// bank.Field = "BankAccount";
    /// bank.DivideBy = 0m;
    /// bank.ForceText = true;
    /// </code>
    /// </example>
    public class ExcelFieldRule
    {
        /// <summary>Tên cột DataTable cần áp quy tắc. Ví dụ "OverFrameSub", "BankAccount".</summary>
        public string Field;
        /// <summary>
        /// Khác 0 thì ghi (giá trị / DivideBy) dạng số. 0 thì không chia.
        /// Ví dụ 100m với phụ cấp phần trăm. ForceText = true thì bỏ qua phép chia và ghi chữ.
        /// </summary>
        public decimal DivideBy;
        /// <summary>
        /// true: luôn ghi chữ, kể cả khi giá trị là số. Dùng cho mã, số tài khoản, số điện thoại.
        /// false: số ghi số, chữ ghi chữ, ngày ghi chữ theo culture hiện tại.
        /// </summary>
        public bool ForceText;
    }
    /// <summary>
    /// Xuất Excel có dòng nhóm từ file mẫu .xlsx.
    /// Copy file mẫu, mở sheet1.xml bằng WindowsBase (reflection, project không cần reference WindowsBase lúc compile), ghi dữ liệu, bật tính lại công thức khi mở file.
    /// Không dùng Excel Interop, không dùng Aspose.
    /// Người gọi chỉ dựng <see cref="ExcelGroupOptions"/> rồi gọi <see cref="Export"/>. Mẫu lương bọc sẵn trong SalaryExcelExporter.
    /// </summary>
    /// <remarks>
    /// Thứ tự việc trong Export:
    /// 1. Kiểm tra options, file mẫu, cột bắt buộc.
    /// 2. Copy file mẫu đè lên đường dẫn lưu.
    /// 3. FillSheet: giữ phần chân, xóa từ hàng nhóm trở xuống, sort, ghi từng nhóm (dòng nhóm + các dòng chi tiết + SUM), đẩy phần chân xuống, ghi CellWrites.
    /// 4. Bật calcMode = auto và xóa calcChain cũ để Excel tính lại SUM khi mở.
    /// Lỗi giữa chừng thì xóa file output.
    /// Token số thứ tự không gắn cứng. Chỗ gọi truyền GlobalOrderField và GroupOrderField.
    /// </remarks>
    public static class ExcelGroupExporter
    {
        /// <summary>Namespace XML của sheet Excel. Mọi thẻ row, c, v, f đều thuộc namespace này.</summary>
        private const string SpreadsheetNamespace = "http://schemas.openxmlformats.org/spreadsheetml/2006/main";
        /// <summary>
        /// Copy file mẫu ra outputPath rồi đổ data theo options.
        /// </summary>
        /// <param name="data">Bảng nguồn. Dòng Deleted bị bỏ. Rỗng thì ném ArgumentException.</param>
        /// <param name="templatePath">Đường dẫn file .xlsx mẫu. Không thấy file thì ném FileNotFoundException.</param>
        /// <param name="outputPath">Đường dẫn file xuất. Thư mục chưa có thì được tạo. File cũ bị ghi đè.</param>
        /// <param name="options">Hàng mẫu, khóa nhóm, cột chi tiết, cột cộng, tiêu đề. Null thì ném ArgumentNullException.</param>
        /// <example>
        /// <code>
        /// ExcelGroupOptions options = new ExcelGroupOptions();
        /// options.GroupPrototypeRow = 8;
        /// options.DetailPrototypeRow = 9;
        /// options.FooterStartRow = 12;
        /// options.GroupKeyField = "GroupIDTest";
        /// options.GroupTitleField = "GroupIDTestName";
        /// options.GroupTitleColumn = "A";
        /// options.DetailFields = new string[] { "DateText", "TheoryQuantity", "LearningContent" };
        /// ExcelGroupExporter.Export(dtbExport, strFilePath, strPathSaveAs, options);
        /// </code>
        /// </example>
        public static void Export(DataTable data, string templatePath, string outputPath, ExcelGroupOptions options)
        {
            if (data == null) throw new ArgumentNullException("data");
            if (options == null) throw new ArgumentNullException("options");
            if (options.DetailFields == null || options.DetailFields.Length == 0)
                throw new ArgumentException("Thiếu danh sách cột chi tiết.", "options");
            if (options.GroupPrototypeRow <= 0 || options.DetailPrototypeRow <= options.GroupPrototypeRow)
                throw new ArgumentException("Hàng nhóm phải nằm trên hàng chi tiết.", "options");
            int footerStart = options.FooterStartRow > 0 ? options.FooterStartRow : options.DetailPrototypeRow + 1;
            if (footerStart <= options.DetailPrototypeRow)
                throw new ArgumentException("Phần chân phải nằm dưới hàng chi tiết.", "options");
            if (String.IsNullOrEmpty(options.GroupKeyField) && String.IsNullOrEmpty(options.GroupKeyFallbackField) && String.IsNullOrEmpty(options.GroupTitleField))
                throw new ArgumentException("Thiếu cột khóa nhóm.", "options");
            if (options.TotalColumns != null || options.TotalFields != null)
            {
                if (options.TotalColumns == null || options.TotalFields == null || options.TotalColumns.Length != options.TotalFields.Length)
                    throw new ArgumentException("TotalColumns và TotalFields phải cùng số phần tử.", "options");
            }
            if (!File.Exists(templatePath)) throw new FileNotFoundException("Không tìm thấy mẫu Excel.", templatePath);
            if (data.Rows.Count == 0) throw new ArgumentException("Không có dữ liệu để xuất.", "data");
            ValidateColumns(data, options);
            string folder = Path.GetDirectoryName(outputPath);
            if (!String.IsNullOrEmpty(folder)) Directory.CreateDirectory(folder);
            File.Copy(templatePath, outputPath, true);
            try
            {
                using (IDisposable package = (IDisposable)OpenPackage(outputPath))
                {
                    object sheetPart = PackageGetPart(package, new Uri("/xl/worksheets/sheet1.xml", UriKind.Relative));
                    XmlDocument sheet = LoadXml(sheetPart);
                    FillSheet(sheet, data, options, footerStart);
                    SaveXml(sheetPart, sheet);
                    UpdateWorkbook(package);
                }
            }
            catch
            {
                try { File.Delete(outputPath); }
                catch (IOException) { }
                catch (UnauthorizedAccessException) { }
                throw;
            }
        }
        /// <summary>
        /// Kiểm tra cột bắt buộc và cột dùng để cộng đều có trong DataTable.
        /// Thiếu thì ném ArgumentException("Dữ liệu thiếu cột ...").
        /// Ví dụ RequiredFields có "DateText" mà bảng không có cột đó thì dừng trước khi copy nội dung sheet.
        /// </summary>
        private static void ValidateColumns(DataTable data, ExcelGroupOptions options)
        {
            if (options.RequiredFields != null)
            {
                foreach (string field in options.RequiredFields)
                    if (!data.Columns.Contains(field))
                        throw new ArgumentException("Dữ liệu thiếu cột " + field + ".", "data");
            }
            if (options.TotalFields != null)
            {
                foreach (string field in options.TotalFields)
                    if (!data.Columns.Contains(field))
                        throw new ArgumentException("Dữ liệu thiếu cột " + field + ".", "data");
            }
        }
        /// <summary>
        /// Ghi sheet1: dòng nhóm, dòng chi tiết, SUM, phần chân, ô tiêu đề.
        /// footerStart là hàng phần chân đã chuẩn hóa (không còn 0).
        /// Ví dụ sổ đầu bài footerStart = 12: giữ hàng chữ ký, xóa hàng 8 trở xuống, ghi lại từ hàng 8.
        /// </summary>
        private static void FillSheet(XmlDocument sheet, DataTable data, ExcelGroupOptions options, int footerStart)
        {
            XmlNamespaceManager ns = new XmlNamespaceManager(sheet.NameTable);
            ns.AddNamespace("m", SpreadsheetNamespace);
            XmlElement sheetData = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:sheetData", ns);
            XmlElement groupPrototype = (XmlElement)sheetData.SelectSingleNode("m:row[@r='" + options.GroupPrototypeRow + "']", ns);
            XmlElement detailPrototype = (XmlElement)sheetData.SelectSingleNode("m:row[@r='" + options.DetailPrototypeRow + "']", ns);
            if (groupPrototype == null || detailPrototype == null)
                throw new InvalidDataException("Mẫu Excel cần hàng nhóm " + options.GroupPrototypeRow + " và hàng chi tiết " + options.DetailPrototypeRow + ".");
            // Giữ phần chân và vùng gộp trước khi xóa hàng mẫu.
            List<XmlElement> footerRows = new List<XmlElement>();
            foreach (XmlNode row in sheetData.SelectNodes("m:row", ns))
                if (Int32.Parse(row.Attributes["r"].Value, CultureInfo.InvariantCulture) >= footerStart)
                    footerRows.Add((XmlElement)row.CloneNode(true));
            List<string[]> footerMerges = ReadFooterMerges(sheet, ns, footerStart);
            List<string[]> groupMerges = ReadGroupMerges(sheet, ns, options.GroupPrototypeRow);
            List<XmlNode> oldRows = new List<XmlNode>();
            foreach (XmlNode row in sheetData.SelectNodes("m:row", ns))
                if (Int32.Parse(row.Attributes["r"].Value, CultureInfo.InvariantCulture) >= options.GroupPrototypeRow)
                    oldRows.Add(row);
            foreach (XmlNode row in oldRows) sheetData.RemoveChild(row);
            List<DataRow> rows = new List<DataRow>();
            foreach (DataRow row in data.Rows)
                if (row.RowState != DataRowState.Deleted) rows.Add(row);
            if (options.SortFields != null && options.SortFields.Length > 0)
            {
                ExcelGroupOptions sortOptions = options;
                rows.Sort(delegate(DataRow left, DataRow right)
                {
                    return CompareRows(left, right, sortOptions);
                });
            }
            int currentRow = options.GroupPrototypeRow;
            int globalOrder = 0;
            int groupOrder = 0;
            int position = 0;
            string[] fields = options.DetailFields;
            string[] totalColumns = options.TotalColumns;
            string[] totalFields = options.TotalFields;
            // Mỗi vòng là một nhóm: dòng nhóm, rồi các dòng chi tiết cùng khóa, rồi SUM.
            while (position < rows.Count)
            {
                int end = position + 1;
                string groupKey = GroupKey(rows[position], options);
                while (end < rows.Count && GroupKey(rows[end], options) == groupKey) end++;
                groupOrder++;
                int groupRowNumber = currentRow++;
                XmlElement groupRow = CloneRow(groupPrototype, groupRowNumber);
                if (!String.IsNullOrEmpty(options.GroupOrderColumn))
                {
                    if (options.GroupOrderAsRoman)
                        SetText(groupRow, options.GroupOrderColumn, groupRowNumber, Roman(groupOrder));
                    else
                        SetNumber(groupRow, options.GroupOrderColumn, groupRowNumber, groupOrder);
                }
                if (!String.IsNullOrEmpty(options.GroupTitleColumn))
                    SetText(groupRow, options.GroupTitleColumn, groupRowNumber, TextValue(rows[position], options.GroupTitleField));
                int firstDetail = currentRow;
                for (int i = position; i < end; i++)
                {
                    globalOrder++;
                    int itemOrder = i - position + 1;
                    XmlElement detailRow = CloneRow(detailPrototype, currentRow);
                    for (int col = 0; col < fields.Length; col++)
                    {
                        string addressColumn = ColumnName(col + 1);
                        string field = fields[col];
                        if (IsOrderField(options.GlobalOrderField, field))
                            SetNumber(detailRow, addressColumn, currentRow, globalOrder);
                        else if (IsOrderField(options.GroupOrderField, field))
                            SetNumber(detailRow, addressColumn, currentRow, itemOrder);
                        else if (data.Columns.Contains(field) && rows[i][field] != DBNull.Value)
                        {
                            ExcelFieldRule rule = FindRule(options, field);
                            if (rule != null && rule.ForceText)
                                SetDataValue(detailRow, addressColumn, currentRow, rows[i][field], true);
                            else if (rule != null && rule.DivideBy != 0m)
                                SetNumber(detailRow, addressColumn, currentRow, Convert.ToDecimal(rows[i][field], CultureInfo.InvariantCulture) / rule.DivideBy);
                            else
                                SetDataValue(detailRow, addressColumn, currentRow, rows[i][field], false);
                        }
                    }
                    sheetData.AppendChild(detailRow);
                    currentRow++;
                }
                if (totalColumns != null)
                {
                    for (int i = 0; i < totalColumns.Length; i++)
                    {
                        decimal total = 0m;
                        for (int detail = position; detail < end; detail++)
                            if (rows[detail][totalFields[i]] != DBNull.Value)
                                total += Convert.ToDecimal(rows[detail][totalFields[i]], CultureInfo.InvariantCulture);
                        SetFormula(groupRow, totalColumns[i], groupRowNumber,
                            "SUM(" + totalColumns[i] + firstDetail + ":" + totalColumns[i] + (currentRow - 1) + ")", total);
                    }
                }
                sheetData.InsertBefore(groupRow, sheetData.SelectSingleNode("m:row[@r='" + firstDetail + "']", ns));
                AddGroupMerges(sheet, ns, groupMerges, groupRowNumber);
                position = end;
            }
            // Đẩy chữ ký xuống đúng số dòng vừa phát sinh. offset = hàng kế tiếp - hàng chân cũ.
            int footerOffset = currentRow - footerStart;
            int lastRow = currentRow - 1;
            foreach (XmlElement footerRow in footerRows)
            {
                int rowNumber = Int32.Parse(footerRow.GetAttribute("r"), CultureInfo.InvariantCulture) + footerOffset;
                footerRow.SetAttribute("r", rowNumber.ToString(CultureInfo.InvariantCulture));
                foreach (XmlNode node in footerRow.ChildNodes)
                {
                    XmlElement cell = node as XmlElement;
                    if (cell != null && cell.LocalName == "c")
                        cell.SetAttribute("r", ColumnLetters(cell.GetAttribute("r")) + rowNumber);
                }
                sheetData.AppendChild(footerRow);
                lastRow = rowNumber;
            }
            AddFooterMerges(sheet, ns, footerMerges, footerOffset);
            if (options.CellWrites != null)
            {
                foreach (ExcelCellWrite cellWrite in options.CellWrites)
                {
                    XmlElement headerRow = (XmlElement)sheetData.SelectSingleNode("m:row[@r='" + cellWrite.Row + "']", ns);
                    if (headerRow == null)
                        throw new InvalidDataException("Không thấy hàng " + cellWrite.Row + " để ghi cột " + cellWrite.Column + ".");
                    SetText(headerRow, cellWrite.Column, cellWrite.Row, cellWrite.Text);
                }
            }
            XmlElement dimension = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:dimension", ns);
            if (dimension != null)
            {
                string[] dimensionAddresses = dimension.GetAttribute("ref").Split(':');
                string existingEnd = dimensionAddresses[dimensionAddresses.Length - 1];
                int lastColumn = Math.Max(fields.Length, ColumnIndex(ColumnLetters(existingEnd)));
                dimension.SetAttribute("ref", "A1:" + ColumnName(lastColumn) + lastRow);
            }
            XmlElement merges = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:mergeCells", ns);
            if (merges != null) merges.SetAttribute("count", merges.ChildNodes.Count.ToString(CultureInfo.InvariantCulture));
        }
        /// <summary>
        /// true khi field trong DetailFields trùng token chỗ gọi truyền vào.
        /// Ví dụ token = "@GlobalOrder", field = "@GlobalOrder" thì đây là cột đếm, không đọc DataTable.
        /// token rỗng thì luôn false.
        /// </summary>
        private static bool IsOrderField(string token, string field)
        {
            return !String.IsNullOrEmpty(token) && field == token;
        }
        /// <summary>
        /// Tìm FieldRules theo tên cột. Không có quy tắc thì trả null và ô ghi theo kiểu mặc định.
        /// Ví dụ field = "BankAccount" trả rule ForceText. field = "Fullname" thường trả null.
        /// </summary>
        private static ExcelFieldRule FindRule(ExcelGroupOptions options, string field)
        {
            if (options.FieldRules == null) return null;
            foreach (ExcelFieldRule rule in options.FieldRules)
                if (rule != null && rule.Field == field) return rule;
            return null;
        }
        /// <summary>
        /// Lấy vùng gộp nằm trọn trên hàng nhóm mẫu, dạng cặp cột "A","G".
        /// Đồng thời xóa mọi merge có hàng cuối từ hàng nhóm trở xuống, để ghi lại merge nhóm và merge chân.
        /// Ví dụ hàng 8 gộp A8:G8 thì kết quả chứa { "A", "G" }. Mỗi dòng nhóm mới sẽ có A{n}:G{n}.
        /// Merge dọc hoặc merge của header phía trên hàng nhóm được giữ nguyên.
        /// </summary>
        private static List<string[]> ReadGroupMerges(XmlDocument sheet, XmlNamespaceManager ns, int groupPrototypeRow)
        {
            List<string[]> prototypeMerges = new List<string[]>();
            XmlElement merges = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:mergeCells", ns);
            if (merges == null) return prototypeMerges;
            List<XmlNode> remove = new List<XmlNode>();
            foreach (XmlNode merge in merges.ChildNodes)
            {
                string[] addresses = merge.Attributes["ref"].Value.Split(':');
                int first = RowNumber(addresses[0]);
                int last = RowNumber(addresses[addresses.Length - 1]);
                if (first == groupPrototypeRow && last == groupPrototypeRow)
                    prototypeMerges.Add(new string[] { ColumnLetters(addresses[0]), ColumnLetters(addresses[addresses.Length - 1]) });
                if (last >= groupPrototypeRow) remove.Add(merge);
            }
            foreach (XmlNode merge in remove) merges.RemoveChild(merge);
            return prototypeMerges;
        }
        /// <summary>
        /// Lấy vùng gộp có hàng bắt đầu từ footerStartRow trở xuống, giữ nguyên địa chỉ ô (chưa cộng offset).
        /// Ví dụ merge E11:G11 khi footer bắt đầu ở 11 được lưu lại, sau đó AddFooterMerges cộng số dòng đã chèn.
        /// </summary>
        private static List<string[]> ReadFooterMerges(XmlDocument sheet, XmlNamespaceManager ns, int footerStartRow)
        {
            List<string[]> footerMerges = new List<string[]>();
            XmlElement merges = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:mergeCells", ns);
            if (merges == null) return footerMerges;
            foreach (XmlNode merge in merges.ChildNodes)
            {
                string[] addresses = merge.Attributes["ref"].Value.Split(':');
                if (RowNumber(addresses[0]) >= footerStartRow)
                    footerMerges.Add(addresses);
            }
            return footerMerges;
        }
        /// <summary>
        /// Gắn lại merge phần chân sau khi đẩy xuống. offset = số hàng cộng thêm.
        /// Ví dụ địa chỉ cũ E12:G12, offset = 30 thì merge mới là E42:G42.
        /// </summary>
        private static void AddFooterMerges(XmlDocument sheet, XmlNamespaceManager ns, List<string[]> footerMerges, int offset)
        {
            XmlElement merges = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:mergeCells", ns);
            if (merges == null) return;
            foreach (string[] addresses in footerMerges)
            {
                XmlElement merge = sheet.CreateElement("mergeCell", SpreadsheetNamespace);
                merge.SetAttribute("ref", ColumnLetters(addresses[0]) + (RowNumber(addresses[0]) + offset)
                    + ":" + ColumnLetters(addresses[addresses.Length - 1])
                    + (RowNumber(addresses[addresses.Length - 1]) + offset));
                merges.AppendChild(merge);
            }
        }
        /// <summary>
        /// Gắn merge ngang của hàng nhóm mẫu lên một dòng nhóm vừa tạo.
        /// Ví dụ mẫu gộp A:G, row = 15 thì tạo merge A15:G15.
        /// </summary>
        private static void AddGroupMerges(XmlDocument sheet, XmlNamespaceManager ns, List<string[]> groupMerges, int row)
        {
            if (groupMerges.Count == 0) return;
            XmlElement merges = (XmlElement)sheet.SelectSingleNode("/m:worksheet/m:mergeCells", ns);
            foreach (string[] columns in groupMerges)
            {
                XmlElement merge = sheet.CreateElement("mergeCell", SpreadsheetNamespace);
                merge.SetAttribute("ref", columns[0] + row + ":" + columns[1] + row);
                merges.AppendChild(merge);
            }
        }
        /// <summary>
        /// Clone hàng mẫu sang số hàng mới. Đổi địa chỉ ô (A8 thành A20) và xóa giá trị, giữ style trên thẻ c.
        /// Vì nội dung mẫu bị xóa, chữ "DateText" hay "GroupIDTest" gõ trong file mẫu không còn trên file xuất.
        /// </summary>
        private static XmlElement CloneRow(XmlElement prototype, int row)
        {
            XmlElement copy = (XmlElement)prototype.CloneNode(true);
            copy.SetAttribute("r", row.ToString(CultureInfo.InvariantCulture));
            foreach (XmlNode node in copy.ChildNodes)
            {
                XmlElement cell = node as XmlElement;
                if (cell == null || cell.LocalName != "c") continue;
                cell.SetAttribute("r", ColumnLetters(cell.GetAttribute("r")) + row);
                while (cell.HasChildNodes) cell.RemoveChild(cell.FirstChild);
                cell.RemoveAttribute("t");
            }
            return copy;
        }
        /// <summary>
        /// Ghi một giá trị DataTable vào ô.
        /// forceText = false và giá trị là số thì ghi số. Chuỗi, DateTime, hoặc ép chữ thì ghi inline string.
        /// Ví dụ Fullname "Nguyễn A" ghi chữ. TheoryQuantity 5 ghi số. BankAccount "0123" với forceText ghi chữ "0123".
        /// </summary>
        private static void SetDataValue(XmlElement row, string col, int rowNumber, object value, bool forceText)
        {
            if (!forceText && value is IConvertible && !(value is string) && !(value is DateTime))
            {
                try
                {
                    decimal number = Convert.ToDecimal(value, CultureInfo.InvariantCulture);
                    SetNumber(row, col, rowNumber, number);
                    return;
                }
                catch (InvalidCastException) { }
                catch (FormatException) { }
            }
            SetText(row, col, rowNumber, Convert.ToString(value, CultureInfo.CurrentCulture));
        }
        /// <summary>
        /// Ghi số vào ô, thuộc tính t bị xóa để Excel hiểu là number. Dấu thập phân theo InvariantCulture (dấu chấm).
        /// Ví dụ SetNumber(row, "D", 15, 6m) tạo ô D15 với thẻ v = 6.
        /// </summary>
        private static void SetNumber(XmlElement row, string col, int rowNumber, decimal value)
        {
            XmlElement cell = GetCell(row, col, rowNumber);
            ClearCellContent(cell);
            XmlElement number = cell.OwnerDocument.CreateElement("v", SpreadsheetNamespace);
            number.InnerText = value.ToString(CultureInfo.InvariantCulture);
            cell.AppendChild(number);
        }
        /// <summary>
        /// Ghi chữ inline (không dùng shared string). Xuống dòng nếu value chứa \n.
        /// Ví dụ tên nhóm "Tuần 1" vào cột A hàng 8.
        /// </summary>
        private static void SetText(XmlElement row, string col, int rowNumber, string value)
        {
            XmlElement cell = GetCell(row, col, rowNumber);
            ClearCellContent(cell);
            cell.SetAttribute("t", "inlineStr");
            XmlElement inline = cell.OwnerDocument.CreateElement("is", SpreadsheetNamespace);
            XmlElement text = cell.OwnerDocument.CreateElement("t", SpreadsheetNamespace);
            text.InnerText = value ?? "";
            inline.AppendChild(text);
            cell.AppendChild(inline);
        }
        /// <summary>
        /// Ghi công thức và giá trị đã tính. Excel mở file sẽ tính lại nhờ UpdateWorkbook.
        /// Ví dụ formula = "SUM(D10:D14)", value = 26, ghi vào cột D của dòng nhóm.
        /// </summary>
        private static void SetFormula(XmlElement row, string col, int rowNumber, string formula, decimal value)
        {
            XmlElement cell = GetCell(row, col, rowNumber);
            ClearCellContent(cell);
            XmlElement f = cell.OwnerDocument.CreateElement("f", SpreadsheetNamespace);
            f.InnerText = formula;
            XmlElement v = cell.OwnerDocument.CreateElement("v", SpreadsheetNamespace);
            v.InnerText = value.ToString(CultureInfo.InvariantCulture);
            cell.AppendChild(f);
            cell.AppendChild(v);
        }
        /// <summary>Xóa con của ô (v, is, f) và bỏ thuộc tính t để ghi giá trị mới, giữ style.</summary>
        private static void ClearCellContent(XmlElement cell)
        {
            while (cell.HasChildNodes) cell.RemoveChild(cell.FirstChild);
            cell.RemoveAttribute("t");
        }
        /// <summary>
        /// Lấy ô theo địa chỉ. Chưa có thì tạo và chèn đúng thứ tự cột (A trước B).
        /// Ví dụ hàng mẫu không có ô D thì GetCell vẫn tạo D15 khi cần ghi UnitSalary.
        /// </summary>
        private static XmlElement GetCell(XmlElement row, string col, int rowNumber)
        {
            string address = col + rowNumber;
            foreach (XmlNode node in row.ChildNodes)
            {
                XmlElement cell = node as XmlElement;
                if (cell != null && cell.LocalName == "c" && cell.GetAttribute("r") == address) return cell;
            }
            XmlElement created = row.OwnerDocument.CreateElement("c", SpreadsheetNamespace);
            created.SetAttribute("r", address);
            int target = ColumnIndex(col);
            foreach (XmlNode node in row.ChildNodes)
            {
                XmlElement cell = node as XmlElement;
                if (cell != null && cell.LocalName == "c" && ColumnIndex(ColumnLetters(cell.GetAttribute("r"))) > target)
                {
                    row.InsertBefore(created, cell);
                    return created;
                }
            }
            row.AppendChild(created);
            return created;
        }
        /// <summary>
        /// So hai dòng theo SortFields. UseGroupKey so khóa nhóm. Numeric so số, trống xếp cuối. Còn lại so chữ.
        /// Trả về âm, 0, dương giống Comparer. Hết mức mà vẫn bằng nhau thì trả 0.
        /// </summary>
        private static int CompareRows(DataRow left, DataRow right, ExcelGroupOptions options)
        {
            foreach (ExcelSortField sort in options.SortFields)
            {
                int result;
                if (sort.UseGroupKey)
                    result = String.Compare(GroupKey(left, options), GroupKey(right, options), StringComparison.OrdinalIgnoreCase);
                else if (sort.Numeric)
                    result = IntegerValue(left, sort.Field, Int32.MaxValue).CompareTo(IntegerValue(right, sort.Field, Int32.MaxValue));
                else
                    result = String.Compare(TextValue(left, sort.Field), TextValue(right, sort.Field), StringComparison.CurrentCultureIgnoreCase);
                if (result != 0) return result;
            }
            return 0;
        }
        /// <summary>
        /// Khóa cắt nhóm của một dòng.
        /// Có GroupKeyField và ô không DBNull: "ID:" + giá trị. Ví dụ DepartmentID = 5 ra "ID:5".
        /// Ngược lại: "NAME:" + cột fallback hoặc cột tiêu đề. Tiền tố ID/NAME tránh số 5 trùng chữ "5".
        /// </summary>
        private static string GroupKey(DataRow row, ExcelGroupOptions options)
        {
            if (!String.IsNullOrEmpty(options.GroupKeyField) && row.Table.Columns.Contains(options.GroupKeyField) && row[options.GroupKeyField] != DBNull.Value)
                return "ID:" + Convert.ToString(row[options.GroupKeyField], CultureInfo.InvariantCulture);
            string fallback = String.IsNullOrEmpty(options.GroupKeyFallbackField) ? options.GroupTitleField : options.GroupKeyFallbackField;
            return "NAME:" + TextValue(row, fallback);
        }
        /// <summary>Đọc chữ từ cột. Không có cột hoặc DBNull thì trả "". Ví dụ TextValue(row, "GroupIDTestName").</summary>
        private static string TextValue(DataRow row, string name)
        {
            return row.Table.Columns.Contains(name) && row[name] != DBNull.Value
                ? Convert.ToString(row[name], CultureInfo.CurrentCulture) : "";
        }
        /// <summary>
        /// Đọc số nguyên từ cột. Không có cột hoặc DBNull thì trả fallback.
        /// Sort số dùng fallback = Int32.MaxValue để dòng trống xuống cuối.
        /// </summary>
        private static int IntegerValue(DataRow row, string name, int fallback)
        {
            return row.Table.Columns.Contains(name) && row[name] != DBNull.Value
                ? Convert.ToInt32(row[name], CultureInfo.InvariantCulture) : fallback;
        }
        /// <summary>
        /// Đổi số thứ tự nhóm thành số La Mã. Chỉ gọi khi GroupOrderAsRoman = true.
        /// Ví dụ 1 = I, 2 = II, 4 = IV, 9 = IX, 40 = XL, 90 = XC, 400 = CD.
        /// Lớn hơn 3999 thì trả về số thường để khỏi viết chuỗi La Mã không chuẩn.
        /// </summary>
        private static string Roman(int value)
        {
            if (value > 3999) return value.ToString(CultureInfo.InvariantCulture);
            int[] numbers = { 1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1 };
            string[] letters = { "M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I" };
            System.Text.StringBuilder text = new System.Text.StringBuilder();
            for (int i = 0; i < numbers.Length; i++)
                while (value >= numbers[i]) { text.Append(letters[i]); value -= numbers[i]; }
            return text.ToString();
        }
        /// <summary>
        /// Đổi số thứ tự cột (1-based) thành chữ Excel. Ví dụ 1 = A, 2 = B, 26 = Z, 27 = AA.
        /// DetailFields[0] dùng ColumnName(1) nên luôn là cột A.
        /// </summary>
        private static string ColumnName(int index)
        {
            string result = "";
            while (index > 0) { index--; result = (char)('A' + index % 26) + result; index /= 26; }
            return result;
        }
        /// <summary>Đổi chữ cột thành số 1-based. Ví dụ "A" = 1, "C" = 3, "AA" = 27. Dùng để chèn ô đúng thứ tự.</summary>
        private static int ColumnIndex(string letters)
        {
            int index = 0;
            foreach (char c in letters) index = index * 26 + c - 'A' + 1;
            return index;
        }
        /// <summary>Lấy phần chữ của địa chỉ ô. Ví dụ "B12" ra "B", "AA3" ra "AA".</summary>
        private static string ColumnLetters(string address)
        {
            int i = 0;
            while (i < address.Length && Char.IsLetter(address[i])) i++;
            return address.Substring(0, i);
        }
        /// <summary>Lấy số hàng của địa chỉ ô. Ví dụ "B12" ra 12, "AA3" ra 3.</summary>
        private static int RowNumber(string address)
        {
            int i = 0;
            while (i < address.Length && Char.IsLetter(address[i])) i++;
            return Int32.Parse(address.Substring(i), CultureInfo.InvariantCulture);
        }
        /// <summary>Đọc XML của một part trong gói xlsx. Tắt XmlResolver để không kéo DTD bên ngoài.</summary>
        private static XmlDocument LoadXml(object part)
        {
            XmlDocument doc = new XmlDocument();
            doc.XmlResolver = null;
            using (Stream stream = (Stream)Call(part, "GetStream",
                new Type[] { typeof(FileMode), typeof(FileAccess) }, FileMode.Open, FileAccess.Read))
                doc.Load(stream);
            return doc;
        }
        /// <summary>Ghi XML trở lại part. FileMode.Create nên nội dung part cũ bị thay hết.</summary>
        private static void SaveXml(object part, XmlDocument doc)
        {
            using (Stream stream = (Stream)Call(part, "GetStream",
                new Type[] { typeof(FileMode), typeof(FileAccess) }, FileMode.Create, FileAccess.Write))
                doc.Save(stream);
        }
        /// <summary>
        /// Bật tính công thức khi mở file: calcMode = auto, fullCalcOnLoad = 1, forceFullCalc = 1.
        /// Xóa xl/calcChain.xml và quan hệ calcChain vì chuỗi tính cũ không còn đúng sau khi chèn hàng.
        /// Không xóa thì Excel có thể hiện SUM sai cho đến khi người dùng sửa một ô.
        /// </summary>
        private static void UpdateWorkbook(object package)
        {
            object workbookPart = PackageGetPart(package, new Uri("/xl/workbook.xml", UriKind.Relative));
            XmlDocument workbook = LoadXml(workbookPart);
            XmlNamespaceManager ns = new XmlNamespaceManager(workbook.NameTable);
            ns.AddNamespace("m", SpreadsheetNamespace);
            XmlElement calculation = (XmlElement)workbook.SelectSingleNode("/m:workbook/m:calcPr", ns);
            if (calculation == null)
            {
                calculation = workbook.CreateElement("calcPr", SpreadsheetNamespace);
                workbook.DocumentElement.AppendChild(calculation);
            }
            calculation.SetAttribute("calcMode", "auto");
            calculation.SetAttribute("fullCalcOnLoad", "1");
            calculation.SetAttribute("forceFullCalc", "1");
            SaveXml(workbookPart, workbook);
            Uri chainUri = new Uri("/xl/calcChain.xml", UriKind.Relative);
            if ((bool)Call(package, "PartExists", new Type[] { typeof(Uri) }, chainUri))
            {
                List<string> relationIds = new List<string>();
                foreach (object relation in (IEnumerable)Call(workbookPart, "GetRelationships", Type.EmptyTypes))
                {
                    Type relationType = relation.GetType();
                    string kind = (string)relationType.GetProperty("RelationshipType").GetValue(relation, null);
                    if (kind.EndsWith("/calcChain", StringComparison.Ordinal))
                        relationIds.Add((string)relationType.GetProperty("Id").GetValue(relation, null));
                }
                foreach (string id in relationIds)
                    Call(workbookPart, "DeleteRelationship", new Type[] { typeof(string) }, id);
                Call(package, "DeletePart", new Type[] { typeof(Uri) }, chainUri);
            }
        }
        /// <summary>
        /// Mở file .xlsx như gói ZIP/XML qua System.IO.Packaging.Package.
        /// Gọi bằng reflection vì project VS2010 không reference WindowsBase lúc biên dịch.
        /// Trả về Package đang mở ReadWrite. Người gọi phải Dispose.
        /// </summary>
        private static object OpenPackage(string path)
        {
            Type type = Type.GetType("System.IO.Packaging.Package, WindowsBase, Version=4.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35", true);
            MethodInfo open = type.GetMethod("Open", new Type[] {
                typeof(string), typeof(FileMode), typeof(FileAccess) });
            return open.Invoke(null, new object[] { path, FileMode.Open, FileAccess.ReadWrite });
        }
        /// <summary>Lấy một part theo URI. Ví dụ "/xl/worksheets/sheet1.xml" hoặc "/xl/workbook.xml".</summary>
        private static object PackageGetPart(object package, Uri uri)
        {
            return Call(package, "GetPart", new Type[] { typeof(Uri) }, uri);
        }
        /// <summary>
        /// Gọi method qua reflection. Không thấy method thì ném MissingMethodException.
        /// Lỗi bên trong Invoke được ném ra InnerException để chỗ gọi thấy lỗi Excel thật, không bị bọc TargetInvocationException.
        /// </summary>
        private static object Call(object target, string method, Type[] parameters, params object[] args)
        {
            MethodInfo member = target.GetType().GetMethod(method, parameters);
            if (member == null) throw new MissingMethodException(target.GetType().FullName, method);
            try { return member.Invoke(target, args); }
            catch (TargetInvocationException ex)
            {
                if (ex.InnerException != null) throw ex.InnerException;
                throw;
            }
        }
    }
}

VÍ DỤ GỌI ExcelGroupExporter CHO SỔ ĐẦU BÀI
File mẫu: Template\Bang ghi tom tat noi dung.xlsx
Nhóm theo cột DataTable GroupIDTest, chữ trên dòng nhóm lấy từ GroupIDTestName.

File mẫu sau khi chèn MỘT hàng nhóm ngay trên hàng DateText:
    Hàng 8  = hàng mẫu dòng nhóm. Trong Excel hãy gộp ô tên nhóm trên hàng này (ví dụ A đến cột vắng mặt).
    Hàng 9  = hàng DateText (bị đẩy xuống từ hàng 8).
    Hàng 12 = hàng "Đồng Nai, ngày..." (phần chân).
Hàng ví dụ 12/01/2019 nằm giữa hàng 9 và hàng 12 nên không ra file.

Thư viện ghi DetailFields từ cột A trở đi:
    A DateText
    B TheoryQuantity
    C PracticeQuantity
    D TestQuantity
    E LearningContent
    F RequestContent
    G OffStudentCountText
    H Rating
    I Description
Nếu trong file mẫu ô DateText không nằm ở cột A thì phải dời khối bảng cho cột đầu là A, rồi mới gọi.

Ô tiêu đề {Lớp}, {Môn}, {Giáo viên} không tự thay như Libs.CExcel.
Muốn ghi thì khai options.CellWrites, mỗi ô một dòng, và ghi CẢ câu trong ô (ví dụ "Tên lớp: 12A1"), vì thư viện thay cả ô.
Số hàng và cột trong CellWrites bên dưới phải mở file mẫu đối lại. Ảnh đang thấy chữ {Lớp} khoảng hàng 2, {Môn} hàng 3, {Giáo viên} hàng 4, {Giáo viên2} khoảng hàng 17.

Trang web List.ascx.cs cần using TKSManager.Salary và reference project TKSManager thì mới gọi được.

