private bool ExportExcel(string outputPath = null)
{
    SIM_ScheduleChecking obj = new SIM_ScheduleChecking();
    DataTable dtbExport = obj.GetDataTable("SIM_ScheduleChecking_SearchForWeb",
                                "@ClassSubjectID", this.ClassSubjectID,
                                "@LoginName", User.UserName,
                                "@TeacherID_Schedule", this.TeacherID_Schedule);
    if (dtbExport == null)
    {
        MsgBox.ShowError("Việc tải dữ liệu bị lỗi!\r\n" + obj.ErrorException.Message);
        return false;
    }
    DataTable dtb = obj.GetDataTable("SIM_Class_Subject_GetInfo", "@ClassSubjectID", this.ClassSubjectID);
    if (dtb == null || dtb.Rows.Count == 0)
    {
        MsgBox.ShowError("Việc lấy thông tin môn học lớp bị lỗi!");
        return false;
    }
    DataRow drw = dtb.Rows[0];
    string strPath = AppDomain.CurrentDomain.BaseDirectory;
    string strFilePath = strPath + "Template\\Bang ghi tom tat noi dung.xlsx";
    string strFileNameSaveAs = "";
    string strPathSaveAs = outputPath;
    if (outputPath == null)
    {
        string strTeacher = this.TeacherID_Schedule != null ? "_" + this.TeacherID_Schedule : "";
        strFileNameSaveAs = "So dau bai_" + WebGlobal.FilterFileName(drw["SubjectName"] + "_" + drw["ClassName"]) + strTeacher + ".xlsx";
        strPathSaveAs = strPath + "Export\\" + strFileNameSaveAs;
    }
    ExcelGroupOptions options = new ExcelGroupOptions();
    options.GroupPrototypeRow = 8;
    options.DetailPrototypeRow = 9;
    options.FooterStartRow = 12;
    options.GroupKeyField = "GroupIDTest";
    options.GroupKeyFallbackField = "GroupIDTestName";
    options.GroupTitleField = "GroupIDTestName";
    options.GroupTitleColumn = "A";
    options.GroupOrderAsRoman = false;
    options.DetailFields = new string[] {
        "DateText", "TheoryQuantity", "PracticeQuantity", "TestQuantity",
        "LearningContent", "RequestContent", "OffStudentCountText", "Rating", "Description"
    };
    options.RequiredFields = new string[] { "GroupIDTestName", "DateText" };
    ExcelSortField sortGroup = new ExcelSortField();
    sortGroup.UseGroupKey = true;
    options.SortFields = new ExcelSortField[] { sortGroup };
    options.CellWrites = new ExcelCellWrite[] {
        TaoO(2, "B", "Tên lớp: " + drw["ClassName"]),
        TaoO(2, "E", "Năm học: " + drw["YearText"] + " - Học kỳ: " + drw["Semester"]),
        TaoO(3, "B", "Môn học/Modun: " + drw["SubjectName"]),
        TaoO(4, "B", "Giáo viên giảng dạy " + drw["TeacherName"]),
        TaoO(17, "E", drw["TeacherName"].ToString())
    };
    try
    {
        ExcelGroupExporter.Export(dtbExport, strFilePath, strPathSaveAs, options);
    }
    catch (Exception ex)
    {
        MsgBox.ShowError("Việc xuất excel thất bại.\r\n" + ex.Message);
        return false;
    }
    if (outputPath == null)
        Response.Redirect(DCore.Globals.ApplicationVRoot + "/DownloadFile.ashx?key=" + DownloadFile.GenerateKeyForExport(strPathSaveAs, strFileNameSaveAs, User.UserName, "Viet$minh"));
    return true;
}
private ExcelCellWrite TaoO(int row, string column, string text)
{
    ExcelCellWrite cell = new ExcelCellWrite();
    cell.Row = row;
    cell.Column = column;
    cell.Text = text;
    return cell;
}
